pub assume_specification[ core::net::IpAddr::to_canonical ](
    address: &core::net::IpAddr,
) -> (result: core::net::IpAddr)
    ensures
        result@ == match address@ {
            vstd::std_specs::net::IpAddrView::V4(bytes) => vstd::std_specs::net::IpAddrView::V4(bytes),
            vstd::std_specs::net::IpAddrView::V6(bytes) => if bytes.len() == 16
                && bytes.subrange(0, 12) == Seq::new(10, |i: int| 0u8) + seq![0xffu8, 0xffu8]
            {
                vstd::std_specs::net::IpAddrView::V4(bytes.subrange(12, 16))
            } else {
                vstd::std_specs::net::IpAddrView::V6(bytes)
            },
        },
;

pub assume_specification[ core::net::Ipv6Addr::from_bits ](
    bits: u128,
) -> (result: core::net::Ipv6Addr)
    ensures
        result@ == seq![(((bits >> 120) & 0xffu128) as u8), (((bits >> 112) & 0xffu128) as u8), (((bits >> 104) & 0xffu128) as u8), (((bits >> 96) & 0xffu128) as u8), (((bits >> 88) & 0xffu128) as u8), (((bits >> 80) & 0xffu128) as u8), (((bits >> 72) & 0xffu128) as u8), (((bits >> 64) & 0xffu128) as u8), (((bits >> 56) & 0xffu128) as u8), (((bits >> 48) & 0xffu128) as u8), (((bits >> 40) & 0xffu128) as u8), (((bits >> 32) & 0xffu128) as u8), (((bits >> 24) & 0xffu128) as u8), (((bits >> 16) & 0xffu128) as u8), (((bits >> 8) & 0xffu128) as u8), ((bits & 0xffu128) as u8)]
;

pub assume_specification[ Ipv6Addr::to_canonical ](
    address: &Ipv6Addr,
) -> (result: IpAddr)
    ensures
        result@ == if address@.subrange(0, 12)
            == Seq::new(10, |i: int| 0u8) + seq![0xffu8, 0xffu8]
        {
            IpAddrView::V4(address@.subrange(12, 16))
        } else {
            IpAddrView::V6(address@)
        },
;

ensures:
final(address)@ == match (old(address)@, new_ip@) {
            (SocketAddrView::V4(old_v4), IpAddrView::V4(ip)) =>
                SocketAddrView::V4(SocketAddrV4View { ip, port: old_v4.port }),
            (SocketAddrView::V4(old_v4), IpAddrView::V6(ip)) =>
                SocketAddrView::V6(SocketAddrV6View {
                    ip,
                    port: old_v4.port,
                    flowinfo: 0,
                    scope_id: 0,
                }),
            (SocketAddrView::V6(old_v6), IpAddrView::V4(ip)) =>
                SocketAddrView::V4(SocketAddrV4View { ip, port: old_v6.port }),
            (SocketAddrView::V6(old_v6), IpAddrView::V6(ip)) =>
                SocketAddrView::V6(SocketAddrV6View {
                    ip,
                    port: old_v6.port,
                    flowinfo: old_v6.flowinfo,
                    scope_id: old_v6.scope_id,
                }),
        }

contract_code:
pub assume_specification[ SocketAddr::set_ip ](
    address: &mut SocketAddr,
    new_ip: IpAddr,
)
    ensures
        final(address)@ == match (old(address)@, new_ip@) {
            (SocketAddrView::V4(old_v4), IpAddrView::V4(ip)) =>
                SocketAddrView::V4(SocketAddrV4View { ip, port: old_v4.port }),
            (SocketAddrView::V4(old_v4), IpAddrView::V6(ip)) =>
                SocketAddrView::V6(SocketAddrV6View {
                    ip,
                    port: old_v4.port,
                    flowinfo: 0,
                    scope_id: 0,
                }),
            (SocketAddrView::V6(old_v6), IpAddrView::V4(ip)) =>
                SocketAddrView::V4(SocketAddrV4View { ip, port: old_v6.port }),
            (SocketAddrView::V6(old_v6), IpAddrView::V6(ip)) =>
                SocketAddrView::V6(SocketAddrV6View {
                    ip,
                    port: old_v6.port,
                    flowinfo: old_v6.flowinfo,
                    scope_id: old_v6.scope_id,
                }),
        },
;

pub assume_specification[ core::time::Duration::as_secs_f32 ](
    duration: &core::time::Duration,
) -> (result: f32)
    ensures
        result == vstd::float::ieee_float_cast::<u64, f32>(
            (duration@ / vstd::std_specs::duration::nanos_per_second()) as u64,
        ) + vstd::float::ieee_float_cast::<u32, f32>(
            (duration@ % vstd::std_specs::duration::nanos_per_second()) as u32,
        ) / vstd::float::ieee_float_cast::<u32, f32>(1_000_000_000u32),
;

pub assume_specification[ core::time::Duration::as_secs_f64 ](
    duration: &core::time::Duration,
) -> (result: f64)
    ensures
        result == vstd::float::ieee_float_cast::<u64, f64>(
            (duration@ / vstd::std_specs::duration::nanos_per_second()) as u64,
        ) + vstd::float::ieee_float_cast::<u32, f64>(
            (duration@ % vstd::std_specs::duration::nanos_per_second()) as u32,
        ) / vstd::float::ieee_float_cast::<u32, f64>(1_000_000_000u32),
;

pub assume_specification[
    core::time::Duration::from_secs_f32
](secs: f32) -> (result: core::time::Duration)
    requires
        {
            let bits = secs.to_bits_abs_spec() as nat;
            (!secs.is_sign_negative_spec() || bits == 0)
                && bits / 0x80_0000 < 191
        },
    ensures
        result@ == {
            let bits = secs.to_bits_abs_spec() as nat;
            let exponent = bits / 0x80_0000;
            let mantissa = bits % 0x80_0000;
            let significand = if exponent == 0 {
                mantissa
            } else {
                0x80_0000 + mantissa
            };
            let numerator = if exponent < 150 {
                1_000_000_000 * significand
            } else {
                1_000_000_000 * significand * pow2((exponent - 150) as nat)
            };
            let denominator = if exponent < 150 {
                if exponent == 0 {
                    pow2(149)
                } else {
                    pow2((150 - exponent) as nat)
                }
            } else {
                1
            };
            let quotient = numerator / denominator;
            let remainder = numerator % denominator;
            if remainder * 2 < denominator {
                quotient
            } else if remainder * 2 > denominator || quotient % 2 == 1 {
                quotient + 1
            } else {
                quotient
            }
        },
;

pub assume_specification[
    core::time::Duration::from_secs_f64
](secs: f64) -> (result: core::time::Duration)
    requires
        {
            let bits = secs.to_bits_abs_spec() as nat;
            (!secs.is_sign_negative_spec() || bits == 0)
                && bits / 0x10_0000_0000_0000 < 1087
        },
    ensures
        result@ == {
            let bits = secs.to_bits_abs_spec() as nat;
            let exponent = bits / 0x10_0000_0000_0000;
            let mantissa = bits % 0x10_0000_0000_0000;
            let significand = if exponent == 0 {
                mantissa
            } else {
                0x10_0000_0000_0000 + mantissa
            };
            let numerator = if exponent < 1075 {
                1_000_000_000 * significand
            } else {
                1_000_000_000 * significand * pow2((exponent - 1075) as nat)
            };
            let denominator = if exponent < 1075 {
                if exponent == 0 {
                    pow2(1074)
                } else {
                    pow2((1075 - exponent) as nat)
                }
            } else {
                1
            };
            let quotient = numerator / denominator;
            let remainder = numerator % denominator;
            if remainder * 2 < denominator {
                quotient
            } else if remainder * 2 > denominator || quotient % 2 == 1 {
                quotient + 1
            } else {
                quotient
            }
        },
;
